// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 depositAmount, uint8 reentryDepth) public {
        vm.assume(depositAmount > 0);
        vm.assume(depositAmount <= type(uint256).max / 2);
        vm.assume(reentryDepth >= 1 && reentryDepth <= 3);

        ReentrantAttacker attacker = new ReentrantAttacker(c, reentryDepth);

        vm.deal(address(attacker), depositAmount);
        vm.prank(address(attacker));
        c.addToBalance{value: depositAmount}();

        bool ok = true;
        vm.prank(address(attacker));
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(c.getBalance(address(attacker)) == 0);
    }
}

contract ReentrantAttacker {
    Reentrance public target;
    uint256 public reentryDepth;
    uint256 public callsMade;

    constructor(Reentrance _target, uint256 _reentryDepth) {
        target = _target;
        reentryDepth = _reentryDepth;
        callsMade = 0;
    }

    receive() external payable {
        if (callsMade < reentryDepth) {
            callsMade++;
            target.withdrawBalance();
        }
    }
}
